<template>
  <view class="page"><jk-page-nav title="健康报告"/><view class="content"><view class="tabs"><view :class="{active:period==='WEEK'}" @tap="change('WEEK')">近7天</view><view :class="{active:period==='MONTH'}" @tap="change('MONTH')">近30天</view></view><view class="hero"><text>血糖健康报告</text><strong>{{report.riskLevelText||'数据不足'}}</strong><small>{{report.startDate||'--'}} 至 {{report.endDate||'--'}}</small></view><view class="card metrics"><view><text>记录次数</text><strong>{{report.recordCount||0}}</strong></view><view><text>平均值</text><strong>{{value(report.averageValue)}}</strong></view><view><text>最高</text><strong>{{value(report.maxValue)}}</strong></view><view><text>最低</text><strong>{{value(report.minValue)}}</strong></view></view><view class="card"><view class="title">时段表现</view><view v-for="x in report.periodStats||[]" :key="x.periodCode" class="line"><text>{{x.periodText||x.periodCode}}</text><text>{{x.recordCount||0}} 次 · 均值 {{value(x.averageValue)}}</text></view><jk-empty v-if="!(report.periodStats||[]).length" text="暂无足够数据"/></view><view class="card"><view class="title">趋势与提醒</view><view class="advice">{{report.summaryText||'健康报告只根据已录入的数据进行统计，不构成医疗诊断。'}}</view><view v-for="x in report.alerts||[]" :key="x.id" class="alert"><text>{{x.riskLevelText||'异常提醒'}}</text><text>{{x.message||x.remark}}</text></view></view><view class="notice">本报告基于本人手工录入、管理员录入或已接入设备同步的数据。设备厂商未启用时不会生成虚假设备数据。</view></view></view>
</template>
<script>
import JkPageNav from '@/components/jk/jk-page-nav.vue';import JkEmpty from '@/components/jk/jk-empty.vue';import{getJkHealthReport}from'@/api/jkV31.js';
export default{components:{JkPageNav,JkEmpty},data(){return{period:'WEEK',report:{}}},onShow(){this.load()},methods:{change(p){this.period=p;this.load()},load(){getJkHealthReport({period:this.period}).then(r=>{this.report=(r&&r.data)||r||{}}).catch(()=>{this.report={summaryText:'当前暂无可生成报告的健康数据。'}})},value(v){return v===null||v===undefined?'--':Number(v).toFixed(1)}}}
</script>
<style scoped>.page{min-height:100vh;background:#f7f9f9}.content{padding:18rpx 22rpx 44rpx}.tabs{display:flex;padding:6rpx;border-radius:18rpx;background:#fff}.tabs view{flex:1;padding:17rpx;text-align:center;color:#7e898e;font-size:23rpx}.tabs .active{border-radius:14rpx;background:#e6faf4;color:#0fa981;font-weight:700}.hero{display:flex;flex-direction:column;align-items:center;margin-top:18rpx;padding:32rpx;border-radius:22rpx;background:linear-gradient(135deg,#16b990,#50d1b3);color:#fff}.hero text{font-size:25rpx}.hero strong{margin-top:14rpx;font-size:42rpx}.hero small{margin-top:10rpx;font-size:20rpx;opacity:.88}.card{margin-top:18rpx;padding:24rpx;border-radius:20rpx;background:#fff}.metrics{display:flex;flex-wrap:wrap}.metrics view{display:flex;width:50%;flex-direction:column;align-items:center;padding:18rpx 0;box-sizing:border-box}.metrics text{color:#8a9498;font-size:20rpx}.metrics strong{margin-top:7rpx;color:#28343a;font-size:29rpx}.title{margin-bottom:12rpx;font-size:27rpx;font-weight:700}.line{display:flex;justify-content:space-between;padding:16rpx 0;border-bottom:1rpx solid #edf1f0;color:#546167;font-size:22rpx}.line text:last-child{color:#7f8a8f}.advice{color:#5e6a70;font-size:22rpx;line-height:1.7}.alert{margin-top:14rpx;padding:16rpx;border-radius:14rpx;background:#fff6e7}.alert text{display:block}.alert text:first-child{color:#bd7b10;font-size:22rpx;font-weight:700}.alert text:last-child{margin-top:6rpx;color:#7e6a4b;font-size:20rpx}.notice{margin:20rpx 8rpx;color:#90999d;font-size:20rpx;line-height:1.6}</style>
